    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.code, serializer);
    sse_encode_f_64(self.weight, serializer);
    sse_encode_String(self.detail, serializer);
  }

  @protected
  void sse_encode_spam_settings(SpamSettings self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_bool(self.enabled, serializer);
    sse_encode_f_64(self.unsureThreshold, serializer);
    sse_encode_f_64(self.spamThreshold, serializer);
    sse_encode_bool(self.dnsblEnabled, serializer);
    sse_encode_String(self.moveToFolder, serializer);
    sse_encode_list_String(self.allowlist, serializer);
    sse_encode_list_String(self.blocklist, serializer);
  }

  @protected
  void sse_encode_spam_status(SpamStatus self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_u_32(self.modelSpamMessages, serializer);
    sse_encode_u_32(self.modelHamMessages, serializer);
    sse_encode_u_32(self.modelTokens, serializer);
    sse_encode_f_64(self.modelConfidence, serializer);
    sse_encode_list_spam_account_status(self.accounts, serializer);
  }

  @protected
  void sse_encode_spam_verdict(SpamVerdict self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_f_64(self.spamProbability, serializer);
    sse_encode_spam_label(self.label, serializer);
    sse_encode_list_spam_reason(self.reasons, serializer);
    sse_encode_f_64(self.bayesLogOdds, serializer);
    sse_encode_f_64(self.bayesConfidence, serializer);
    sse_encode_f_64(self.rulesScore, serializer);
    sse_encode_f_64(self.logOdds, serializer);
  }

  @protected
  void sse_encode_stored_spam_info(
    StoredSpamInfo self,
