  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_opt_box_autoadd_f_64(self.score, serializer);
    sse_encode_opt_box_autoadd_spam_label(self.label, serializer);
    sse_encode_list_spam_reason(self.reasons, serializer);
    sse_encode_opt_box_autoadd_spam_label(self.learned, serializer);
  }

  @protected
  void sse_encode_sync_event(SyncEvent self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_sync_event_kind(self.kind, serializer);
    sse_encode_opt_box_autoadd_sync_progress(self.progress, serializer);
    sse_encode_opt_box_autoadd_sync_report(self.report, serializer);
  }

  @protected
  void sse_encode_sync_event_kind(
    SyncEventKind self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_i_32(self.index, serializer);
  }

  @protected
  void sse_encode_sync_phase(SyncPhase self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_i_32(self.index, serializer);
  }

  @protected
  void sse_encode_sync_progress(SyncProgress self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.account, serializer);
    sse_encode_String(self.folder, serializer);
    sse_encode_sync_phase(self.phase, serializer);
    sse_encode_u_32(self.fetched, serializer);
    sse_encode_u_32(self.stored, serializer);
    sse_encode_u_32(self.planned, serializer);
    sse_encode_u_32(self.totalKnown, serializer);
    sse_encode_u_32(self.local, serializer);
    sse_encode_bool(self.moreToBackfill, serializer);
