  @protected
  void sse_encode_sync_report(SyncReport self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.account, serializer);
    sse_encode_u_32(self.new_, serializer);
    sse_encode_u_32(self.decrypted, serializer);
